package dev.alien.client.scene;
import dev.alien.client.config.*;import com.google.gson.Gson;import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
public class SceneConfigTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 @Test public void legacyProfilesKeepAllNewEffectsOff(){ClientConfig c=new Gson().fromJson("{\"hud\":{\"enabled\":true},\"cosmetics\":{\"self\":{\"back\":\"WINGS\"}}}",ClientConfig.class);c.normalize();assertFalse(c.scenes.enabled);assertEquals("Natural",c.scenes.mode);assertEquals("Off",c.scenes.sky);assertEquals("WINGS",c.cosmetics.self.back);assertTrue(c.hud.enabled);}
 @Test public void invalidInputsCannotReachShadersAsNonFiniteUniforms(){SceneConfig c=new SceneConfig();c.mode="bad";c.sky=null;c.radius=Float.POSITIVE_INFINITY;c.strength=Float.NaN;c.chromaMemory=-7;c.normalize();assertEquals("Natural",c.mode);assertEquals("Off",c.sky);assertEquals(5,c.radius,0);assertEquals(.85f,c.strength,0);assertEquals(1,c.chromaMemory,0);assertEquals(9,SceneConfig.SKIES.length);}
 @Test public void historiesExpireStayBoundedAndIgnoreInvalidCoordinates(){SceneHistory h=new SceneHistory();h.add(Double.NaN,0,0,0,4);assertEquals(0,h.size());for(int i=0;i<50;i++)h.add(i,2,3,i,4);assertEquals(4,h.size());assertEquals(46,h.x(0),0);assertEquals(1,h.age(3,50),0);h.expire(52,4);assertEquals(2,h.size());h.clear();assertTrue(Double.isInfinite(h.lastDistanceSq(0,0,0)));}
 @Test public void realSavedProfileRestoresSceneAndCosmeticPreferencesTogether()throws Exception{ConfigStore s=new ConfigStore(temp.newFolder());s.load();s.config().scenes.enabled=true;s.config().scenes.mode="Chroma";s.config().scenes.sky="BlackHole";s.config().cosmetics.self.capeShimmer=true;s.config().cosmetics.saveLook(1,s.config().cosmetics.self);s.saveProfile("scenes");s.config().scenes=new SceneConfig();assertTrue(s.loadProfile("scenes"));assertEquals("Chroma",s.config().scenes.mode);assertEquals("BlackHole",s.config().scenes.sky);assertTrue(s.config().cosmetics.loadLook(1).capeShimmer);}
 @Test public void cuteFaceHasActualTransparentArtAndBlinkFrames(){java.awt.image.BufferedImage open=ScenePlayerLayer.faceTexture(false),blink=ScenePlayerLayer.faceTexture(true);assertEquals(0,open.getRGB(0,0));int different=0,painted=0;for(int y=0;y<64;y++)for(int x=0;x<64;x++){if(open.getRGB(x,y)!=blink.getRGB(x,y))different++;if((open.getRGB(x,y)>>>24)>0)painted++;}assertTrue(different>100);assertTrue(painted>400&&painted<2400);}
}
